from collections import deque
from typing import List

class Solution:
    def canMouseWin(self, grid: List[str], catJump: int, mouseJump: int) -> bool:
        rows, cols = len(grid), len(grid[0])
        total = rows * cols
        for r in range(rows):
            for c in range(cols):
                ch = grid[r][c]
                if ch == 'M':
                    mouse0 = r * cols + c
                elif ch == 'C':
                    cat0 = r * cols + c
                elif ch == 'F':
                    food = r * cols + c

        # moves[p] = cells reachable from p in one move (staying put included).
        # The move graph is symmetric, so it also lists the predecessors of p.
        def build(jump):
            moves = [[] for _ in range(total)]
            for r in range(rows):
                for c in range(cols):
                    if grid[r][c] == '#':
                        continue
                    p = r * cols + c
                    moves[p].append(p)
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        for k in range(1, jump + 1):
                            nr, nc = r + dr * k, c + dc * k
                            if not (0 <= nr < rows and 0 <= nc < cols) or grid[nr][nc] == '#':
                                break
                            moves[p].append(nr * cols + nc)
            return moves

        mouse_moves, cat_moves = build(mouseJump), build(catJump)

        UNKNOWN, MOUSE, CAT = 0, 1, 2
        # state = (mouse, cat, turn); turn 0 = mouse to move, 1 = cat to move
        def idx(m, c, t):
            return (m * total + c) * 2 + t

        result = [UNKNOWN] * (total * total * 2)
        degree = [0] * (total * total * 2)   # moves not yet known to be losing for the mover
        for m in range(total):
            for c in range(total):
                degree[idx(m, c, 0)] = len(mouse_moves[m])
                degree[idx(m, c, 1)] = len(cat_moves[c])

        queue = deque()
        def settle(m, c, t, res):
            result[idx(m, c, t)] = res
            queue.append((m, c, t))

        # Terminal states
        for p in range(total):
            if not mouse_moves[p]:
                continue                      # wall cell
            for t in (0, 1):
                settle(p, p, t, CAT)          # cat catches mouse (also if both on food)
                if p != food:
                    settle(food, p, t, MOUSE) # mouse on food, cat elsewhere
                    settle(p, food, t, CAT)   # cat on food, mouse elsewhere

        # Retrograde BFS: propagate known results to predecessor states
        while queue:
            m, c, t = queue.popleft()
            res = result[idx(m, c, t)]
            if t == 1:   # predecessor: mouse was to move from pm
                for pm in mouse_moves[m]:
                    s = idx(pm, c, 0)
                    if result[s] != UNKNOWN:
                        continue
                    if res == MOUSE:
                        settle(pm, c, 0, MOUSE)
                    else:
                        degree[s] -= 1
                        if degree[s] == 0:
                            settle(pm, c, 0, CAT)
            else:        # predecessor: cat was to move from pc
                for pc in cat_moves[c]:
                    s = idx(m, pc, 1)
                    if result[s] != UNKNOWN:
                        continue
                    if res == CAT:
                        settle(m, pc, 1, CAT)
                    else:
                        degree[s] -= 1
                        if degree[s] == 0:
                            settle(m, pc, 1, MOUSE)

        # Undecided (drawn / endless) games count as a cat win
        return result[idx(mouse0, cat0, 0)] == MOUSE
